/* Visual landing: short copy, working product previews, no invented outcomes. */
let landingPreview='night';
function landingPreviewMarkup(view){
 if(view==='path')return `<div class="wl-demo-path"><span class="wl-demo-kicker">YOUR 28-DAY PATH · EXAMPLE</span><h3>Small steps.<br>Something to keep.</h3><div class="wl-path-nodes"><span class="done">✓</span><i></i><span class="current">✦</span><i></i><span>☾</span><i></i><span>★</span></div><p>Understand → Try → Reflect</p><a href="#demo" class="wl-demo-link">Explore the app ${icon('arrow')}</a></div>`;
 if(view==='nights')return `<div class="wl-demo-trend"><span class="wl-demo-kicker">YOUR NIGHTS IN PERSPECTIVE · EXAMPLE</span><h3>A pattern.<br>Not a score.</h3><div class="wl-trend-bars" role="img" aria-label="Illustrative awakenings over seven nights: 3, 2, 3, 1, 2, 1, 2">${[3,2,3,1,2,1,2].map((n,i)=>`<div><span>${n}</span><i style="--bar:${n*28}%"></i><small>${['M','T','W','T','F','S','S'][i]}</small></div>`).join('')}</div><a href="#demo" class="wl-demo-link">Explore the app ${icon('arrow')}</a></div>`;
 return `<div class="wl-demo-night"><span class="wl-demo-kicker">YOUR QUIET RESET · STEP 1 OF 3</span><div class="wl-breathe" aria-hidden="true"><span>☾</span></div><h3>You’re awake.<br>Make a little space.</h3><p>Nothing to solve right now.</p><a href="#night-reset" class="wl-demo-link">Try the night reset ${icon('arrow')}</a></div>`;
}
function renderLanding(){main.innerHTML=`<div class="wl-landing">
<section class="wl-hero" id="home"><div class="wl-hero-copy"><span class="wl-kicker"><i></i> FOR THE NIGHTS THAT DON’T GO TO PLAN</span><h1>Wide awake.<br><em>Again?</em></h1><p>Understand what may wake you at 3am.<br>Have a calmer next step ready.</p>${btn('Find my 3am pattern','#quiz')}<div class="wl-hero-meta"><span>12 questions · About 3 minutes</span><span>Free profile. No email needed.</span></div><a href="#inside" class="wl-underlink">Take a look inside <span>↓</span></a></div><div class="wl-hero-visual"><img class="wl-night-photo" src="assets/night-v5.webp" alt="A woman awake in a softly lit bedroom" width="900" height="900" fetchpriority="high"><div class="wl-photo-shade"></div><div class="wl-night-clock" aria-hidden="true">3<span>:</span>07<span class="wl-clock-am"> am</span></div><div class="wl-night-thought thought-one">Tomorrow’s to-do list</div><div class="wl-night-thought thought-two">“What if I can’t sleep?”</div><div class="wl-hero-caption"><span>LESS GUESSING. ONE QUIET NEXT STEP.</span><strong>There’s a way to<br>meet this moment.</strong></div></div></section>
<div class="wl-trust-strip"><span>${icon('moon')} Support for an awake moment</span><span>${icon('book')} 28 short daily lessons</span><span>${icon('check')} Designed for life after 40</span></div>
<section class="section wl-section" id="how"><div class="wl-section-heading"><span class="wl-kicker">A LITTLE UNDERSTANDING GOES A LONG WAY</span><h2>Less figuring it out.<br>More <em>“I know what to do.”</em></h2></div><div class="wl-feature-grid"><a class="wl-feature" href="#quiz"><div class="wl-factor-art" aria-hidden="true"><span class="wl-orbit orbit-one"></span><span class="wl-orbit orbit-two"></span><span class="wl-factor-moon">☾</span><span class="wl-factor-tag">Busy mind</span><span class="wl-factor-tag second">Daily rhythm</span><span class="wl-factor-star">✦</span></div><span class="wl-feature-number">01 / UNDERSTAND</span><h3>Find your pattern.</h3><p>A few questions. Possible factors.<br>A starting point that fits.</p><span class="wl-feature-arrow">Find my pattern ↗</span></a><a class="wl-feature" href="#night-reset"><div class="wl-window-art" aria-hidden="true"><div class="wl-window"><span>☾</span><i></i><i></i><i></i></div><div class="wl-bed"><i></i><i></i></div><div class="wl-window-label">One quiet next step</div></div><span class="wl-feature-number">02 / IN THE MOMENT</span><h3>Know what to try.</h3><p>A gentle three-step reset.<br>No clock watching required.</p><span class="wl-feature-arrow">Try the night reset ↗</span></a><a class="wl-feature" href="#program"><div class="wl-journal-art" aria-hidden="true"><div class="wl-journal"><span>Today, I noticed…</span><i></i><i></i><i></i><b>✦</b></div><span class="wl-pencil"></span><span class="wl-cup">☕</span></div><span class="wl-feature-number">03 / BUILD YOUR TOOLKIT</span><h3>Take one small step.</h3><p>Short lessons. Real-life practices.<br>At a pace that feels right.</p><span class="wl-feature-arrow">See the 28-day path ↗</span></a></div></section>
<section class="wl-showcase" id="inside"><div class="wl-showcase-copy"><span class="wl-kicker">A LOOK INSIDE SLEEPTHROUGH</span><h2>Less noise.<br><em>More clarity.</em></h2><p>For the middle of the night.<br>And the mornings after.</p><div class="wl-preview-tabs" role="group" aria-label="Choose an app preview">${[['night','Your 3am reset', 'moon'],['path','Your daily practice','book'],['nights','Your sleep picture','chart']].map(([id,label,i])=>`<button data-showcase="${id}" aria-pressed="${landingPreview===id}">${icon(i)}<span>${label}</span><span>↗</span></button>`).join('')}</div><small>Illustrative screens. Your profile starts with your answers.</small></div><div class="wl-demo-frame"><div class="wl-demo-top"><span>☾ SleepThrough</span><span>✦</span></div><div id="landing-preview-panel" aria-live="polite">${landingPreviewMarkup(landingPreview)}</div></div></section>
<section class="section wl-section wl-program" id="program"><div class="wl-program-photo"><img src="assets/morning-v5.webp" alt="A woman taking a quiet moment to write in a notebook beside a sunlit window" width="1000" height="800" loading="lazy"><span class="wl-photo-label">A little space for yourself.</span></div><div class="wl-program-copy"><span class="wl-kicker">YOUR 28-DAY SLEEP RESET</span><h2>Ten minutes.<br>One small skill.<br><em>Your own pace.</em></h2><p>A clear path through the thoughts,<br>habits and routines around your nights.</p><div class="wl-week-row"><span><b>01</b> Notice</span><span><b>02</b> Unwind</span><span><b>03</b> Repeat</span><span><b>04</b> Continue</span></div>${btn('Find my starting point','#quiz')}<small>28 days is a learning path, not a promised recovery time.</small></div></section>
<section class="section wl-section wl-faq" id="faq"><div><span class="wl-kicker">GOOD TO KNOW</span><h2>A little clarity.<br>Before you begin.</h2><p>Practical, self-guided sleep skills.<br>No wearable required.</p></div><div>${[['Is the sleep profile free?','Yes. Answer 12 questions and explore your profile without an email or payment details.'],['Will this tell me why I wake up?','It highlights possible factors and explains which answers informed them. It does not establish a medical cause or diagnose insomnia.'],['What is in the 28-day reset?','Short lessons, practical exercises, a morning diary and a three-step night reset. Most lessons take 5–10 minutes.'],['Can I move at my own pace?','Yes. Revisit a practice or return after a break. Sign in to save your learning and diary across devices.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section>
<section class="wl-final"><span class="wl-final-moon" aria-hidden="true">☾</span><span class="wl-kicker">START WITH UNDERSTANDING</span><h2>Your next night.<br><em>A clearer plan.</em></h2>${btn('Find my 3am pattern','#quiz')}<p>About 3 minutes. One practical next step.</p></section>
${footer()}<p class="wl-wellness-note">Self-guided wellness learning. If sleep difficulties persist or affect daily life, speak with a qualified healthcare professional.</p></div>`;}
document.addEventListener('click',e=>{const button=e.target.closest('button[data-showcase]');if(!button)return;landingPreview=button.dataset.showcase;const panel=document.getElementById('landing-preview-panel');if(!panel)return;panel.innerHTML=landingPreviewMarkup(landingPreview);document.querySelectorAll('[data-showcase]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.showcase===landingPreview)));});

const quizBrief=[{"title":"What would you like to change?","options":["Wake less often","Get back to sleep","Quiet my mind","Feel more rested"]},{"title":"How long has this been happening?","hint":"Your best estimate is enough."},{"title":"How often do you wake at night?","hint":"Think about a typical week."},{"title":"When do you tend to wake?","options":["Soon after falling asleep","In the middle of the night","Earlier than I want","It changes"]},{"title":"How long do you feel awake?","hint":"Estimate from memory. No clock watching."},{"title":"What happens when you wake?","options":["Thoughts and to-do lists","Worrying about sleep","Light, sound or comfort","I’m not sure"]},{"title":"A busy mind before bed?","hint":"Think about the last two weeks."},{"title":"What do you usually do next?","options":["Check the time","Open my phone or work","Rest quietly","It varies"]},{"title":"How steady is your sleep routine?","options":["Quite consistent","It shifts by about an hour","Weekends are very different","It changes a lot"]},{"title":"Your last half-hour before bed?","options":["Work or planning","Scrolling or watching","A quiet wind-down","Different each evening"]},{"title":"What feels hardest the next day?","options":["Focus","Mood","Energy","It varies"]},{"title":"What would help you get started?","options":["An evening practice","A step for when I wake","A morning check-in","A flexible daily lesson"]}];
